import java.util.*;class RiverCutoffTest{public static void main(String[]a){List<RiverRibbon.Point> loop=new ArrayList<>();loop.add(new RiverRibbon.Point(550,700,5,90));for(int i=0;i<=160;i++){double t=Math.PI+2*Math.PI*i/160.;loop.add(new RiverRibbon.Point(650+50*Math.cos(t),700+50*Math.sin(t),5,90));}loop.add(new RiverRibbon.Point(600,820,5,90));List<RiverRibbon.Cutoff> abandoned=new ArrayList<>();var result=RiverRibbon.cutoff(loop,abandoned,EnvironmentMap.filled(128*128,92),128,8);if(abandoned.size()!=1||result.size()>loop.size()-60)throw new AssertionError("No actual meander neck cutoff");var w=new TerraForge.World(512,62,83);Arrays.fill(w.height,92);var e=w.environment;e.water=EnvironmentMap.filled(512*512,62);e.river=new float[512*512];e.material=new byte[512*512];e.snow=new float[512*512];RiverRibbon.abandoned(w,512,512,62,abandoned.get(0));int wet=0;for(int i=0;i<e.height.length;i++)if(e.waterY(i,62)>Math.round(e.height[i]))wet++;if(wet<500)throw new AssertionError("Abandoned bend not retained as oxbow");System.out.println("PASS: cutoff derives from a real returning meander and retains its abandoned wet path, without random pond placement");}}
